// Package app wires process configuration to the HTTP server dependencies.
package app

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"

	"benchmark.local/iam/internal/config"
	"benchmark.local/iam/internal/domain"
	"benchmark.local/iam/internal/repository"
)

// App is the top-level HTTP application. Domain dependencies are added here as
// they are introduced, keeping construction in one place.
type App struct {
	cfg     config.Config
	handler http.Handler
	users   *repository.UserRepository
	clock   domain.Clock
}

const maxJSONBodySize int64 = 1 << 20

// New constructs an application from validated configuration.
func New(cfg config.Config) (*App, error) {
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", health)
	mux.HandleFunc("GET /readyz", health)
	users := repository.NewUserRepository()
	application := &App{cfg: cfg, users: users, clock: domain.RealClock{}}
	mux.HandleFunc("POST /v1/register", application.register)
	application.handler = withRequestID(mux)
	return application, nil
}

// Handler returns the HTTP handler used by cmd/iamd.
func (a *App) Handler() http.Handler { return a.handler }

// Server returns a configured net/http server.
func (a *App) Server() *http.Server {
	return &http.Server{
		Addr:         a.cfg.Address,
		Handler:      a.handler,
		ReadTimeout:  a.cfg.ReadTimeout,
		WriteTimeout: a.cfg.WriteTimeout,
		IdleTimeout:  a.cfg.IdleTimeout,
	}
}

func health(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, dataEnvelope{Data: map[string]string{"status": "ok"}})
}

type registerRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

type dataEnvelope struct {
	Data any `json:"data"`
}

type errorEnvelope struct {
	Error errorBody `json:"error"`
}

type errorBody struct {
	Code      string `json:"code"`
	Message   string `json:"message"`
	RequestID string `json:"request_id"`
}

func (a *App) register(w http.ResponseWriter, r *http.Request) {
	requestID := requestID(r)
	w.Header().Set("X-Request-ID", requestID)
	var input registerRequest
	if err := decodeJSON(r, &input); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", "invalid request body", requestID)
		return
	}
	email, err := domain.ValidateEmail(input.Email)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", "invalid email", requestID)
		return
	}
	material, err := domain.HashPassword(input.Password)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", err.Error(), requestID)
		return
	}
	id, err := domain.NewUserID()
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", "internal server error", requestID)
		return
	}
	now := a.clock.Now().UTC()
	user := domain.User{
		ID:                     id,
		Email:                  email,
		EmailVerificationState: domain.EmailVerificationPending,
		PasswordMaterial:       material,
		CreatedAt:              now,
		UpdatedAt:              now,
	}
	if err := a.users.Create(user); err != nil {
		if domain.IsKind(err, domain.ErrConflict) {
			writeError(w, http.StatusConflict, "conflict", "email already exists", requestID)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", "internal server error", requestID)
		return
	}
	writeJSON(w, http.StatusCreated, dataEnvelope{Data: user.PublicProfile()})
}

func decodeJSON(r *http.Request, destination any) error {
	limited := &countingReader{reader: io.LimitReader(r.Body, maxJSONBodySize+1)}
	decoder := json.NewDecoder(limited)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(destination); err != nil {
		return err
	}
	if limited.count > maxJSONBodySize {
		return errors.New("request body too large")
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return errors.New("multiple JSON values")
		}
		return err
	}
	if limited.count > maxJSONBodySize {
		return errors.New("request body too large")
	}
	return nil
}

type countingReader struct {
	reader io.Reader
	count  int64
}

func (r *countingReader) Read(p []byte) (int, error) {
	n, err := r.reader.Read(p)
	r.count += int64(n)
	return n, err
}

func withRequestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("X-Request-ID", requestID(r))
		next.ServeHTTP(w, r)
	})
}

func requestID(r *http.Request) string {
	if value := strings.TrimSpace(r.Header.Get("X-Request-ID")); value != "" {
		return value
	}
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err == nil {
		return hex.EncodeToString(raw[:])
	}
	return "unknown"
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}

func writeError(w http.ResponseWriter, status int, code, message, requestID string) {
	writeJSON(w, status, errorEnvelope{Error: errorBody{Code: code, Message: message, RequestID: requestID}})
}
// Package config contains the process configuration and its validation.
package config

import (
	"crypto/rand"
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
	"time"
)

const (
	defaultAddress       = ":8080"
	defaultIssuer        = "iam"
	defaultAccessTTL     = 15 * time.Minute
	defaultRefreshTTL    = 30 * 24 * time.Hour
	defaultReadTimeout   = 10 * time.Second
	defaultWriteTimeout  = 10 * time.Second
	defaultIdleTimeout   = 60 * time.Second
	defaultShutdownGrace = 10 * time.Second
)

// Config is the immutable configuration used to construct the service.
// HMACSecret is kept as bytes so callers do not need to repeatedly convert it.
type Config struct {
	Address         string
	Issuer          string
	HMACSecret      []byte
	AccessTTL       time.Duration
	RefreshTTL      time.Duration
	ReadTimeout     time.Duration
	WriteTimeout    time.Duration
	IdleTimeout     time.Duration
	ShutdownGrace   time.Duration
	LoginRateLimit  int
	APIKeyRateLimit int
}

// Load reads IAM_* environment variables and validates the resulting config.
// IAM_HMAC_SECRET is mandatory and must contain at least 32 bytes.
func Load() (Config, error) {
	secret := os.Getenv("IAM_HMAC_SECRET")
	if secret == "" {
		return Config{}, errors.New("IAM_HMAC_SECRET is required")
	}

	c := Config{
		Address:         envString("IAM_ADDRESS", defaultAddress),
		Issuer:          envString("IAM_ISSUER", defaultIssuer),
		HMACSecret:      []byte(secret),
		AccessTTL:       envDuration("IAM_ACCESS_TTL", defaultAccessTTL),
		RefreshTTL:      envDuration("IAM_REFRESH_TTL", defaultRefreshTTL),
		ReadTimeout:     envDuration("IAM_READ_TIMEOUT", defaultReadTimeout),
		WriteTimeout:    envDuration("IAM_WRITE_TIMEOUT", defaultWriteTimeout),
		IdleTimeout:     envDuration("IAM_IDLE_TIMEOUT", defaultIdleTimeout),
		ShutdownGrace:   envDuration("IAM_SHUTDOWN_GRACE", defaultShutdownGrace),
		LoginRateLimit:  envInt("IAM_LOGIN_RATE_LIMIT", 10),
		APIKeyRateLimit: envInt("IAM_APIKEY_RATE_LIMIT", 60),
	}
	if err := c.Validate(); err != nil {
		return Config{}, err
	}
	return c, nil
}

// Validate rejects unsafe or unusable runtime settings.
func (c Config) Validate() error {
	if strings.TrimSpace(c.Address) == "" {
		return errors.New("address must not be empty")
	}
	if strings.TrimSpace(c.Issuer) == "" {
		return errors.New("issuer must not be empty")
	}
	if len(c.HMACSecret) < 32 {
		return errors.New("HMAC secret must be at least 32 bytes")
	}
	for name, value := range map[string]time.Duration{
		"access TTL": c.AccessTTL, "refresh TTL": c.RefreshTTL,
		"read timeout": c.ReadTimeout, "write timeout": c.WriteTimeout,
		"idle timeout": c.IdleTimeout, "shutdown grace": c.ShutdownGrace,
	} {
		if value <= 0 {
			return fmt.Errorf("%s must be positive", name)
		}
	}
	if c.RefreshTTL < c.AccessTTL {
		return errors.New("refresh TTL must not be shorter than access TTL")
	}
	if c.LoginRateLimit <= 0 || c.APIKeyRateLimit <= 0 {
		return errors.New("rate limits must be positive")
	}
	return nil
}

// GenerateSecret returns a cryptographically random secret suitable for local setup.
func GenerateSecret(size int) ([]byte, error) {
	if size < 32 {
		return nil, errors.New("secret size must be at least 32 bytes")
	}
	b := make([]byte, size)
	if _, err := rand.Read(b); err != nil {
		return nil, fmt.Errorf("generate secret: %w", err)
	}
	return b, nil
}

func envString(key, fallback string) string {
	if value := strings.TrimSpace(os.Getenv(key)); value != "" {
		return value
	}
	return fallback
}

func envDuration(key string, fallback time.Duration) time.Duration {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	duration, err := time.ParseDuration(value)
	if err != nil {
		return -1
	}
	return duration
}

func envInt(key string, fallback int) int {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	result, err := strconv.Atoi(value)
	if err != nil {
		return -1
	}
	return result
}
// Package domain contains shared IAM domain primitives.
package domain

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
)

// ID is the common representation of an entity identifier. Values are UUID
// version 4 strings, generated with crypto/rand.
type ID string

type UserID ID
type OrganizationID ID
type SessionID ID
type InviteID ID
type RoleID ID
type APIKeyID ID
type TokenFamilyID ID

// NewID returns a new random UUID version 4 identifier.
func NewID() (ID, error) {
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		return "", fmt.Errorf("generate id: %w", err)
	}
	value[6] = (value[6] & 0x0f) | 0x40
	value[8] = (value[8] & 0x3f) | 0x80
	encoded := make([]byte, 36)
	hex.Encode(encoded[0:8], value[0:4])
	hex.Encode(encoded[9:13], value[4:6])
	hex.Encode(encoded[14:18], value[6:8])
	hex.Encode(encoded[19:23], value[8:10])
	hex.Encode(encoded[24:36], value[10:16])
	encoded[8], encoded[13], encoded[18], encoded[23] = '-', '-', '-', '-'
	return ID(encoded), nil
}

func newTypedID[T ~string](newValue func() (ID, error)) (T, error) {
	id, err := newValue()
	return T(id), err
}

func NewUserID() (UserID, error) { return newTypedID[UserID](NewID) }

func NewOrganizationID() (OrganizationID, error) { return newTypedID[OrganizationID](NewID) }

func NewSessionID() (SessionID, error) { return newTypedID[SessionID](NewID) }

func NewInviteID() (InviteID, error) { return newTypedID[InviteID](NewID) }

func NewRoleID() (RoleID, error) { return newTypedID[RoleID](NewID) }

func NewAPIKeyID() (APIKeyID, error) { return newTypedID[APIKeyID](NewID) }

func NewTokenFamilyID() (TokenFamilyID, error) { return newTypedID[TokenFamilyID](NewID) }

// ParseID validates the textual UUID representation before converting it to ID.
func ParseID(value string) (ID, error) {
	if len(value) != 36 || value[8] != '-' || value[13] != '-' || value[18] != '-' || value[23] != '-' {
		return "", errors.New("invalid id")
	}
	var raw [16]byte
	if _, err := hex.Decode(raw[:4], []byte(value[0:8])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[4:6], []byte(value[9:13])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[6:8], []byte(value[14:18])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[8:10], []byte(value[19:23])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[10:16], []byte(value[24:36])); err != nil {
		return "", errors.New("invalid id")
	}
	return ID(value), nil
}
package domain

import "time"

// Clock supplies the current time to domain services. Injecting it keeps
// domain behavior deterministic and independent of the global clock.
type Clock interface {
	Now() time.Time
}

// RealClock is the production clock implementation.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now().UTC() }

// ClockFunc adapts a function to Clock and is useful for deterministic callers.
type ClockFunc func() time.Time

func (f ClockFunc) Now() time.Time { return f() }
